import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_as_a_nonconversion():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions():
    groups = {"a": [{"converted": True}], "b": [{"converted": False}] * 3, "c": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"c": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 5), (4, 6)])
def test_trailing_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected


def test_parse_fields_and_skip_lines():
    assert parse_session_log(["", " \t", "  # ignored", " a , 1 , 0 ", " b , 2 , "]) == [
        {"id": "a", "day": 1, "converted": False},
        {"id": "b", "day": 2, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["id,1", "id,1,0,extra", "id,bad,0"])
def test_parse_error_includes_input_position(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log(["  # comment", "", bad_line])


def test_dedupe_keeps_last_occurrence_and_sorts_survivors():
    events = parse_session_log(["a,8,0", "c,1,1", "b,2,0", "a,2,1"])
    assert dedupe_sessions(events) == [events[1], events[3], events[2]]


def test_daily_counts_include_only_days_in_range():
    events = parse_session_log(["a,1,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    assert daily_conversion_counts(events, 2, 4) == [2, 0, 0]
    assert daily_conversion_counts(events, 4, 2) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_session_log(["a,1,1", "b,4,1", "c,4,0"]), "b": []}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 1}
    assert campaign_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"z": [{"converted": True}], "b": [], "a": [{"converted": True}], "c": [{"converted": False}]}
    assert top_converting_groups(groups, 4) == ["a", "z", "c"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("c", 0.0), ("z", 1.0)]


def test_streak_resets_on_nonpositive_counts():
    assert longest_conversion_streak([1, 2, 0, 1, -1, 1]) == 2
    assert longest_conversion_streak([]) == 0

